import{_ as d,o,c as a,ag as t}from"./chunks/framework.BZohXCq9.js";const b=JSON.parse('{"title":"Teacher Dashboard -> Feedback (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/feedback.md","filePath":"modules/teacher-dashboard/feedback.md"}'),s={name:"modules/teacher-dashboard/feedback.md"};function l(c,e,r,n,i,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="teacher-dashboard-feedback-deep" tabindex="-1">Teacher Dashboard -&gt; Feedback (deep) <a class="header-anchor" href="#teacher-dashboard-feedback-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Feedback (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>feedback</code><br><strong>Routes:</strong> <code>/teacher-dashboard/feedback</code>, <code>/teacher-dashboard/feedbackForm/:bookingId/:lessonId/:studentId</code></p><p>This module lets instructors give lesson-based feedback to students after completed lessons.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show completed lessons that are eligible for instructor feedback.</li><li>Open a feedback form per completed lesson slot.</li><li>Create, update, or delete lesson feedback.</li><li>Track slot-level feedback status and student lesson-hours adjustments.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/CompleteBookings.tsx</code></td><td>Feedback queue page</td><td>Calls <code>GET_COMPLETED_STUDENT_BOOKINGS</code>; lists completed lesson slots and links into feedback form route.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/FeedBackForm.tsx</code></td><td>Feedback form page</td><td>Uses <code>useFeedback</code> hook and lesson/student route params.</td></tr><tr><td><code>Frontend/src/hooks/UseFeedBack.ts</code></td><td>Main feedback hook</td><td>Wraps lesson-feedback queries and mutations.</td></tr><tr><td><code>Frontend/src/graphql/Queries/LessonFeedback.ts</code></td><td>Lesson feedback GraphQL</td><td>Defines <code>GET_FEEDBACK_BY_LESSON_ID</code>, <code>CREATE_FEEDBACK</code>, <code>UPDATE_FEEDBACK</code>, <code>DELETE_FEEDBACK</code>, <code>GET_STUDENT_LESSON_HOURS</code>.</td></tr><tr><td><code>Frontend/src/graphql/mutations/studentBooking.ts</code></td><td>Booking query source</td><td>Defines <code>GET_COMPLETED_STUDENT_BOOKINGS</code>.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="feedback-queue" tabindex="-1">Feedback queue <a class="header-anchor" href="#feedback-queue" aria-label="Permalink to &quot;Feedback queue&quot;">​</a></h3><ul><li><code>GET_COMPLETED_STUDENT_BOOKINGS</code><ul><li>Used by <code>CompleteBookings.tsx</code></li><li>Returns completed bookings/slots for instructor feedback workflow</li></ul></li></ul><h3 id="feedback-form-flow" tabindex="-1">Feedback form flow <a class="header-anchor" href="#feedback-form-flow" aria-label="Permalink to &quot;Feedback form flow&quot;">​</a></h3><ul><li><code>GET_FEEDBACK_BY_LESSON_ID</code></li><li><code>CREATE_FEEDBACK</code></li><li><code>UPDATE_FEEDBACK</code></li><li><code>DELETE_FEEDBACK</code></li><li><code>GET_STUDENT_LESSON_HOURS</code></li></ul><p>These are wrapped by <code>useFeedback</code> and consumed by <code>FeedBackForm.tsx</code>.</p><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/LessonFeedbackTypes.js</code></li><li>Relevant query fields: <ul><li><code>getFeedbackByLessonId</code></li><li><code>getAllFeedbacks</code></li></ul></li><li>Relevant mutation fields: <ul><li><code>createFeedback</code></li><li><code>updateFeedback</code></li><li><code>deleteFeedback</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/LessonFeedBack.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getFeedbackByLessonId</code></li><li><code>Mutation.createFeedback</code></li><li><code>Mutation.updateFeedback</code></li><li><code>Mutation.deleteFeedback</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/LessonFeedBack.js</code></td><td>Stores lesson feedback entries</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Tracks slot-level <code>feedBackStatus</code></td></tr><tr><td><code>server/src/models/User.js</code></td><td>Stores student lesson-hours values adjusted by feedback logic</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens <code>/teacher-dashboard/feedback</code>.</li><li><code>CompleteBookings.tsx</code> loads completed bookings using <code>GET_COMPLETED_STUDENT_BOOKINGS</code>.</li><li>Each completed slot links to <code>/teacher-dashboard/feedbackForm/:bookingId/:lessonId/:studentId</code>.</li><li><code>FeedBackForm.tsx</code> reads params and uses <code>useFeedback</code>.</li><li>Hook loads any existing feedback and student lesson-hours context.</li><li>Create/update/delete actions call the lesson-feedback mutations.</li><li>Backend stores feedback, updates related slot feedback state, and can adjust student lesson-hours values.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The “Feedback From Students” section on the queue page is currently placeholder/coming-soon content, so the live logic is focused on instructors giving feedback to students.</li><li>This module is tightly linked to completed lesson slots rather than being a standalone feedback system.</li></ul>',24)])])}const k=d(s,[["render",l]]);export{b as __pageData,k as default};
